-- Script HANA para cargar COM_CARREFOUR_JOURNAL_UMBRALCUENTA
-- Fuente: CargaUmbrales.xls
-- Nota: una fila del Excel (NUMERO_CUENTA = 25210243) viene sin nombre/comentario.
--       Por eso el JOIN se hace por NUMERO. Si querés forzarlo también por NOMBRE,
--       agregá: AND IFNULL(c."NOMBRE",'') = IFNULL(src."NOMBRE_CUENTA",'')

INSERT INTO "COM_CARREFOUR_JOURNAL_UMBRALCUENTA"
(
    "ID",
    "CREATEDAT",
    "CREATEDBY",
    "MODIFIEDAT",
    "MODIFIEDBY",
    "CUENTACONTAB",
    "IMPORTEGERENCIA",
    "IMPORTECFO",
    "COMENTARIOS"
)
SELECT
    NEWUID()                AS "ID",
    CURRENT_TIMESTAMP       AS "CREATEDAT",
    'MIGRACION'             AS "CREATEDBY",
    CURRENT_TIMESTAMP       AS "MODIFIEDAT",
    'MIGRACION'             AS "MODIFIEDBY",
    c."ID"                  AS "CUENTACONTAB",
    src."IMPORTEGERENCIA"   AS "IMPORTEGERENCIA",
    src."IMPORTECFO"        AS "IMPORTECFO",
    src."COMENTARIOS"       AS "COMENTARIOS"
FROM
(
    SELECT '24700000' AS "NUMERO_CUENTA", 'GC-Previsión Deudore' AS "NOMBRE_CUENTA", 9999999999999.00 AS "IMPORTEGERENCIA", 9999999999999.00 AS "IMPORTECFO", 'GC-Previsión Deudore' AS "COMENTARIOS" FROM DUMMY
UNION ALL
